# -*- coding: utf-8 -*-
"""Glossário do Manual de Radiestesia para Negócios."""
TEORIAS = []
GLOSSARIO = [
    ("Testemunho", "Representação do que se mede à distância: nome completo de quem pede; razão social e endereço da empresa; endereço ou planta do imóvel; matrícula ou planta do terreno; resumo numerado de uma proposta. A lápis, em papel branco novo."),
    ("Biômetro", "Gráfico de medida com escala ou setores (percentual, Bovis, leque) sobre o qual o pêndulo indica um valor ou uma categoria."),
    ("Leque", "Gráfico em semicírculo de 180 graus, com o vértice na base e setores; o pêndulo oscila no vértice e se alinha ao setor da resposta."),
    ("Leque em branco", "Leque numerado (G109 com oito setores, G110 com doze) para listas escritas no caderno: candidatos, projetos, preços, pontos, meses. O manual fica fixo; a lista fica no caderno, datada."),
    ("Bissecção", "Navegação de listas por sim ou não, dividindo ao meio: coluna, metade das linhas, linha, item. Nunca varrer."),
    ("Giro horário", "Na convenção do manual: sim, favorável, repõe. Anti-horário: não, desfavorável, extrai. Parado: neutro ou concluído."),
    ("Convenção de respostas", "Movimentos combinados no início da sessão para pronto, sim, não, nenhuma das anteriores e “não posso ou não devo” (G1)."),
    ("Trio de permissão", "Três perguntas antes de medir: posso? devo? estou pronto? Em negócios, a terceira inclui “tenho pedido de quem responde por isto?”."),
    ("Autoauditoria", "Percentual de influência do desejo do operador na leitura (G2). Acima de 30, parar. Decisões de dinheiro são as que mais contaminam."),
    ("Formulações convergentes", "A mesma pergunta dita de duas ou três maneiras (“é favorável aceitar?”, “é melhor recusar?”). Só vale se as respostas coincidirem; divergiu, “sem resposta hoje”."),
    ("Tendência", "O que o pêndulo devolve: uma inclinação para a conversa, nunca uma ordem. “O pêndulo indica tendência; a decisão é sua.”"),
    ("Empate", "Diferença menor que 10 pontos entre duas opções. A decisão volta à pessoa, pelos critérios dela."),
    ("Critério de peso", "Dois ou três critérios que o pêndulo aponta como os que mais pesam numa decisão; uma opção forte neles vence uma opção forte na média."),
    ("Matriz opções × critérios", "Tabela da ficha de decisão: uma linha por critério (G106, G107, G112, G116, G120), uma coluna por opção numerada, o percentual em cada célula, o peso de cada critério e a decisão por opção."),
    ("Pré-mortem", "Antes de decidir, imaginar que o projeto já falhou daqui a doze meses e perguntar a causa, lida sobre os critérios do G107. Técnica de Gary Klein, adotada como passo opcional."),
    ("Higiene de decisão", "Conjunto de controles que reduz ruído e viés: pergunta escrita antes, critérios antes das opções, taxa de base, avaliação independente, cegamento, formulações convergentes, pré-mortem, registro e revisão, taxa de acerto, palpite como insumo."),
    ("Taxa de base", "Quantas decisões desse tipo deram certo, historicamente, na empresa ou no mercado. Consultada antes do palpite."),
    ("Taxa de acerto", "Quantas leituras do operador se confirmaram na revisão de 90 dias, por tipo de pergunta. É o único termômetro honesto da própria sensibilidade."),
    ("Regra do terceiro", "A outra pessoa (sócio, funcionário, cliente, candidato) entra só como parte da relação de quem pede. Pendular a pessoa dela como pessoa exige autorização explícita."),
    ("Função e momento", "O que se pendula quando a decisão é sobre pessoas da equipe: “esta vaga é necessária?”, “é hora de contratar?”. Nunca a pessoa, nunca a seleção."),
    ("Afinidade comercial", "Leitura do G106 para cliente, fornecedor ou proposta: valores, visão, complementaridade, confiança, comunicação, comprometimento, capacidade financeira, risco, saída, sintonia geral, do lado de quem decide."),
    ("Bovis", "Unidade de vitalidade (G3). 6.500 é a divisa; abaixo de 4.500, limpeza antes de tudo; 8.000 a 10.000, lugar que nutre."),
    ("Planta quadriculada", "Método de levantamento de um terreno ou imóvel: planta orientada com bússola, quadrícula de 2,5 cm, Bovis em cada cruzamento, curvas de isofrequência, redes e veios anotados em cima."),
    ("Geopatia", "Perturbação atribuída ao subsolo: veios d'água, falhas, redes Hartmann e Curry, nós. Mapeada por radiestesia; radônio e campos eletromagnéticos são medidos por instrumento."),
    ("Memória de parede", "Energia que um imóvel guarda de quem o ocupou: negócio anterior, brigas, falência. Tratada com caiação, limpeza e consagração antes de abrir."),
    ("Emissor", "Gráfico que atua enquanto fica montado com o testemunho (Prosperador, Harmonia, Desembaraçador). Só com testemunho da própria empresa ou de quem pediu; nunca sobre terceiros; renovado a cada 14 dias."),
    ("Desimpregnador", "Gráfico para descarregar objetos, papéis e testemunhos antes do uso e entre usos."),
    ("Lei do contragolpe", "Regra dos Servranx para o Psicoprotetor: nunca tentar “devolver” o que veio de fora; proteger e pôr limites."),
    ("Laudo complementar", "Entrega de uma análise radiestésica de terreno ou imóvel: planta anotada, datada e assinada, mais a lista do que fica com sondagem geotécnica, laudo ambiental, medição de radônio e campos e análise jurídica."),
    ("Diagnóstico 360", "Sessão trimestral com o G3 e as onze áreas do G92, duas áreas aprofundadas e três prioridades devolvidas ao dono."),
    ("Diário de decisões", "Registro de cada decisão medida: pergunta exata, resposta, grau, confiança, decisão tomada e, em 90 dias, o que aconteceu. Julga o processo, não só o resultado."),
]
